public function test_when_user_is_replaying_an_activity(): void
{
    /**
     * create activity with a form (with 1 section and all fields)
     * Activity must be replayable
     */
    $form = Form::factory()->has(
        \App\FormBuilder\Models\FormSection::factory()->withFields(),
        'sections'
    )->create();
    $activity = \App\Models\Activity::factory()->create();
    $activity->form()->save($form);
    $activity->replayable = true;
    $activity->save();

    /**
     * Assume that this is happened in the past! User has given ALL answers.
     */
    $formResponse = FormResponse::create([
        'form_id' => $form->id,
        'user_id' => $this->user->id,
        'uuid' => Str::uuid(),
    ]);
    $oldUuid = Str::uuid();
    $activityAR = UserActivityAggregateRoot::retrieve($oldUuid)
        ->beginActivity(
            $activity,
            $this->user,
            $formResponse,
        )->persist();
    $form->fields->each(function (FormField $field) use ($formResponse) {
        app(FormResponseService::class)->appendAnswer(
            $formResponse,
            $field->id,
            fake()->words(3, true),
        );
    });
    $this->assertTrue($formResponse->isCompleted());
    $activityAR->completeActivity($activity, $this->user)->persist();


    /**
     * Now user is trying to play the same activity again.
     * Old response is already completed.
     */
    $oldFLow = UserActivity::byUserAndActivity($this->user, $activity)->first();
    $this->assertNotNull($oldFLow);
    $this->assertEquals($oldFLow->form_response_id, $formResponse->id);
    $this->assertEquals($oldFLow->activity_id, $activity->id);
    $this->assertTrue($oldFLow->formResponse->isCompleted());
    $this->assertTrue($this->user->completedActivities()->pluck('activity_id')->contains($activity->id));
    $this->assertTrue($oldFLow->isCompleted());

    //when the user restart the activity, the uuid must be different
    $response = $this->get(route('missione-start', [
        'id' => $activity->id,
    ]));

    // get the redirect url from response
    $redirectUrl = $response->headers->get('Location');
    $this->assertNotNull($redirectUrl);

    $segments = explode('/', $redirectUrl);
    $newUuid = $segments[count($segments) - 2];
    $this->assertNotEquals($oldUuid, $newUuid);

}


public function test_when_user_is_replaying_an_activity_that_cannot_be_replayed(): void
{
    /**
     * create activity with a form (with 1 section and all fields)
     * Activity is NOT replayable
     */
    $form = Form::factory()->has(
