    $activity->replayable = false;
    $activity->save();

    /**
     * Assume that this is happened in the past! User has given ALL answers.
     */
    $formResponse = FormResponse::create([
        'form_id' => $form->id,
        'user_id' => $this->user->id,
        'uuid' => Str::uuid(),
    ]);
    $oldUuid = Str::uuid();
    $activityAR = UserActivityAggregateRoot::retrieve($oldUuid)
        ->beginActivity(
            $activity,
            $this->user,
            $formResponse,
        )->persist();
    $form->fields->each(function (FormField $field) use ($formResponse) {
        app(FormResponseService::class)->appendAnswer(
            $formResponse,
            $field->id,
            fake()->words(3, true),
        );
    });
    $this->assertTrue($formResponse->isCompleted());
    $activityAR->completeActivity($activity, $this->user)->persist();


    /**
     * Now user is trying to play the same activity again.
     * Old response is already completed.
     */
    $oldFLow = UserActivity::byUserAndActivity($this->user, $activity)->first();
    $this->assertNotNull($oldFLow);
    $this->assertEquals($oldFLow->form_response_id, $formResponse->id);
    $this->assertEquals($oldFLow->activity_id, $activity->id);
